  reasoningCalls += 1;

  const unresolved1 = unresolvedFromAssessment(assessment1);
  state = {
    ...state,
    assessment: assessment1,
    unresolvedQuestions: unresolved1,
    status: unresolved1.length > 0 ? "needs-follow-up" : "complete",
  };

